SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @A bigint=(SELECT CHECKSUM_AGG(BINARY_CHECKSUM(KeyValue,Payload)) FROM lab.FF100),@B bigint=(SELECT CHECKSUM_AGG(BINARY_CHECKSUM(KeyValue,Payload)) FROM lab.FF080);IF (SELECT COUNT_BIG(*) FROM lab.FF100)<>120000 OR @A<>@B THROW 51006,'FAIL_RESULT_CONTRACT: Tabellen sind nicht ergebnisgleich.',1;SELECT * FROM lab.Evidence ORDER BY Stage,TableName;DECLARE @S100 bigint=(SELECT a.LeafAllocations-b.LeafAllocations FROM lab.Evidence a JOIN lab.Evidence b ON b.TableName=a.TableName AND b.Stage='BASELINE' WHERE a.Stage='AFTER_INSERT' AND a.TableName='FF100'),@S80 bigint=(SELECT a.LeafAllocations-b.LeafAllocations FROM lab.Evidence a JOIN lab.Evidence b ON b.TableName=a.TableName AND b.Stage='BASELINE' WHERE a.Stage='AFTER_INSERT' AND a.TableName='FF080');IF @S80>=@S100 BEGIN PRINT 'SQLPERF_SUMMARY|WARN|WARN_EMPIRICAL_VARIANCE';RETURN;END;PRINT 'SQLPERF_SUMMARY|PASS|OK';
